import{_ as e,c as i,o as t,ag as s}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"隐私选择","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy-choices.md","filePath":"zh-CN/guide/privacy-choices.md","lastUpdated":1791311600000}'),r={name:"zh-CN/guide/privacy-choices.md"};function l(n,a,h,o,c,d){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="隐私选择" tabindex="-1">隐私选择 <a class="header-anchor" href="#隐私选择" aria-label="Permalink to &quot;隐私选择&quot;">​</a></h1><p>nPlyr 是一款本地优先的应用。由于你的数据留在你的设备上，我们不会收集、出售或共享任何个人信息。</p><h2 id="我们本地保存的数据" tabindex="-1">我们本地保存的数据 <a class="header-anchor" href="#我们本地保存的数据" aria-label="Permalink to &quot;我们本地保存的数据&quot;">​</a></h2><p>nPlyr 将所有数据本地保存在你的设备上：</p><ul><li>观看历史、书签与下载内容</li><li>应用偏好与主题</li><li>小程序变量（仅在本地存储中，且仅来自你导入的规则）</li><li>调试日志（若启用）</li></ul><p>这些数据都不会被应用本身上传到任何服务器。</p><h2 id="网络由用户主导" tabindex="-1">网络由用户主导 <a class="header-anchor" href="#网络由用户主导" aria-label="Permalink to &quot;网络由用户主导&quot;">​</a></h2><p>nPlyr 仅在流媒体、下载、浏览或运行你选择的某个小程序时使用网络。没有云端 AI 功能，也没有账号，因此没有需要选择加入或退出的事项——应用根本不会把你的数据发送给我们。</p><h2 id="你的权利" tabindex="-1">你的权利 <a class="header-anchor" href="#你的权利" aria-label="Permalink to &quot;你的权利&quot;">​</a></h2><p>由于 nPlyr 不在我们的服务器上收集或存储个人数据，也就没有可供我们访问、删除或转移的个人数据。你所有的数据都可以在应用内直接管理，或通过移除应用的容器文件夹来管理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nPlyr</span></span></code></pre></div><h2 id="不出售" tabindex="-1">不出售 <a class="header-anchor" href="#不出售" aria-label="Permalink to &quot;不出售&quot;">​</a></h2><p>nPlyr 不出售任何个人信息。我们不使用任何第三方的分析、广告或追踪服务。</p><h2 id="联系" tabindex="-1">联系 <a class="header-anchor" href="#联系" aria-label="Permalink to &quot;联系&quot;">​</a></h2><p>如果你对隐私选择有疑问，请在以下地址提交 issue： <code>https://github.com/nPlyr/nPlyr-site/issues</code></p>',15)])])}const b=e(r,[["render",l]]);export{u as __pageData,b as default};
